package pl.ks.profiling.safepoint.analyzer.commons.shared

import pl.ks.profiling.io.InputUtils
import pl.ks.profiling.safepoint.analyzer.commons.shared.gc.parser.GCLogCycleEntry
import pl.ks.profiling.safepoint.analyzer.commons.shared.report.JvmLogFile
import spock.lang.Requires
import spock.lang.Shared
import spock.lang.Specification

import java.util.zip.GZIPInputStream

/**
 * Parses every log from gc-log-samples (generated by gc-log-generator for several JDKs, collectors, locales and
 * platforms) and compares the results with counts taken directly from the raw log.
 */
@Requires({ SampleLogsSpec.SAMPLES_DIR.isDirectory() })
class SampleLogsSpec extends Specification {
    static final File SAMPLES_DIR = new File(System.getProperty("gcLogSamplesDir", "../gc-log-samples"))

    @Shared
    Map<String, JvmLogFile> parsed = [:]

    def "#file: parses without errors and creates pages"() {
        when:
        JvmLogFile result = parse(file, feature, collector)

        then:
        result.pages.find { it.menuName == "Summary" }
        result.pages.size() > 5

        where:
        [file, feature, collector] << samples()
    }

    def "#file: GC collections match the log"() {
        given:
        JvmLogFile result = parse(file, feature, collector)
        RawLog raw = RawLog.read(file)
        def cycles = result.gcLogFile.cycleEntries

        expect: "every collection of the log is parsed"
        cycles.size() == raw.expectedCollections(feature, collector)

        and: "timestamps, durations and heap sizes are sane"
        cycles.every { it.timeStamp != null && it.timeStamp >= 0 && it.timeStamp < 600 }
        cycles.every { it.timeMs != null && it.timeMs >= 0 }
        cycles.sum { it.timeMs } > 0
        cycles.every { it.heapBeforeGCMb >= 0 && it.heapAfterGCMb >= 0 && it.heapSizeMb >= -1 && it.heapSizeMb <= 1024 }
        result.gcLogFile.cycleEntriesWithHeapSizes.size() >= cycles.size() * 0.8
        cycles.collect { it.timeStamp } == cycles.collect { it.timeStamp }.sort()

        and: "decimal parts are kept regardless of the decimal separator (ZGC logs whole cycles in ms precision)"
        cycles.any { cycle -> ([cycle.timeMs] + cycle.subPhasesTime.values()).any { it.stripTrailingZeros().scale() > 0 } }

        and: "collections are recognized (G1 concurrent start and prepare mixed pauses are not genuine)"
        cycles.count { it.genuineCollection } > 0
        // Young, young piggybacks, mixed, remark, cleanup and full for G1; one or two kinds for the others
        cycles*.aggregatedPhase.unique().size() <= 6
        result.gcLogFile.stats.reasonCount == null || result.gcLogFile.stats.reasonCount.keySet().every { it ==~ /[A-Za-z].*/ }

        and: "to-space exhaustion, age tables and survivor statistics are found"
        cycles.count { it.wasToSpaceExhausted } == raw.toSpaceExhaustedCount()
        (cycles.count { !it.bytesInAges.isEmpty() } > 0) == raw.hasAgeTables()
        (cycles.count { it.desiredSurvivorSize > 0 } > 0) == raw.has("Desired survivor size")

        where:
        [file, feature, collector] << samples()
    }

    def "#file: G1 details match the log"() {
        given:
        JvmLogFile result = parse(file, feature, collector)
        RawLog raw = RawLog.read(file)
        def gc = result.gcLogFile

        expect:
        gc.concurrentCycleEntries.size() == raw.expectedConcurrentCycles(feature)
        gc.concurrentCycleEntries.every { it.time != null && it.time >= 0 }
        gc.cycleEntries.any { it.aggregatedPhase == GCLogCycleEntry.MIXED_COLLECTION }
        gc.cycleEntries.any { !it.subPhasesTime.isEmpty() }
        feature == 8 || gc.cycleEntries.any { !it.regionsBeforeGC.isEmpty() }
        feature == 8 || gc.cycleEntries.any { !it.regionsSizeAfterGC.isEmpty() }
        feature == 8 || gc.cycleEntries.sum { it.liveHumongousSizes.size() + it.deadHumongousSizes.size() } > 0

        where:
        [file, feature, collector] << samples().findAll { it[2] == "g1" }
    }

    def "#file: safepoints match the log"() {
        given:
        JvmLogFile result = parse(file, feature, collector)
        def safepoints = result.safepointLogFile.safepoints

        expect:
        safepoints.size() == RawLog.read(file).expectedSafepoints(feature)
        safepoints.every { it.operationName != null && !it.operationName.isBlank() }
        safepoints.every { it.ttsTime >= 0 && it.stoppedTime >= it.ttsTime && it.applicationTime >= 0 }

        where:
        [file, feature, collector] << samples()
    }

    def "#file: threads, classes, JIT, TLAB and string deduplication match the log"() {
        given:
        JvmLogFile result = parse(file, feature, collector)
        RawLog raw = RawLog.read(file)

        expect: "threads"
        result.threadLogFile.threadsStatuses.size() == raw.count(/\[os,thread\s*\] Thread (".*" started|started|attached|finished)/)
        result.threadLogFile.lastStatus.currentCount >= 0

        and: "classes"
        result.classLoaderLogFile.classStatuses.size() == raw.count(/\[class,load\s*\]/) + raw.count(/\[class,unload\s*\].*unloading class/)
        result.classLoaderLogFile.lastStatus.currentCount > 0

        and: "JIT"
        def jit = result.jitLogFile
        jit.compilationStatuses.size() > 0
        [jit.lastStatus.tier1CurrentCount, jit.lastStatus.tier2CurrentCount, jit.lastStatus.tier3CurrentCount,
         jit.lastStatus.tier4CurrentCount].every { it >= 0 }
        jit.lastStatus.tier3CurrentCount > 0 && jit.lastStatus.tier4CurrentCount > 0
        jit.codeCacheStatuses.values().sum(0) { it.size() } == raw.count(/codecache,sweep.*size=/)
        jit.codeCacheSweeperActivities.size() == raw.count(/codecache,sweep,start/)

        and: "TLAB"
        result.tlabLogFile.tlabSummaries.size() == raw.count(/TLAB totals/)
        result.tlabLogFile.threadTlabsBeforeGC.size() > 0

        and: "string deduplication (a report is complete when the next one starts)"
        def reports = raw.count(/(Total Exec|Total Process):/)
        reports == 0 || result.stringDedupLogFile.entries.size() >= reports - 1
        reports == 0 || result.stringDedupLogFile.entries.size() > 0

        where:
        [file, feature, collector] << samples().findAll { it[1] > 8 }
    }

    private JvmLogFile parse(String file, int feature, String collector) {
        return parsed.computeIfAbsent(file) {
            def source = InputUtils.getLogsSource([new File(SAMPLES_DIR, file)], ParserUtils::getTimeStamp)
            def service = new StatsService()
            def ignored = { p -> }
            if (feature == 8) {
                return service.createAllStatsJdk8(source, ignored, ignored)
            } else if (collector.startsWith("shenandoah")) {
                return service.createAllStatsShenandoah(source, ignored, ignored)
            } else if (collector == "zgc") {
                return service.createAllStatsZgc(source, ignored, ignored)
            }
            return service.createAllStatsUnifiedLogger(source, ignored, ignored)
        }
    }

    /**
     * [file, feature version, collector] of every sample listed in samples.tsv.
     */
    static List<List<Object>> samples() {
        if (!SAMPLES_DIR.isDirectory()) {
            return []
        }
        return new File(SAMPLES_DIR, "samples.tsv").readLines().drop(1).collect { it.split("\t") }
                .collect { [it[0], it[4] as int, it[6]] }
    }

    /**
     * Counts taken directly from a raw log, independently of the parsers.
     */
    static class RawLog {
        private static final Map<String, RawLog> CACHE = [:]
        final List<String> lines

        private RawLog(List<String> lines) {
            this.lines = lines
        }

        static synchronized RawLog read(String file) {
            return CACHE.computeIfAbsent(file) {
                new RawLog(new GZIPInputStream(new FileInputStream(new File(SAMPLES_DIR, file))).getText("UTF-8").readLines())
            }
        }

        int count(String regex) {
            def pattern = ~regex
            return lines.count { pattern.matcher(it).find() }
        }

        boolean has(String text) {
            return lines.any { it.contains(text) }
        }

        int distinctIds(String regex) {
            def pattern = ~regex
            return lines.collect { def m = pattern.matcher(it); m.find() ? m.group(1) : null }.findAll().unique().size()
        }

        int expectedCollections(int feature, String collector) {
            if (feature == 8) {
                return count(/\[GC pause|\[Full GC|\[GC \(|\[GC cleanup|\[GC remark/)
            }
            if (collector == "zgc") {
                return distinctIds(/\]\[gc\s*\] GC\((\d+)\) (Garbage|Major|Minor) Collection/)
            }
            if (collector.startsWith("shenandoah")) {
                return distinctIds(/\]\[gc,start\s*\] GC\((\d+)\)/)
            }
            return count(/\]\[gc\s*\] GC\(\d+\) Pause /)
        }

        int expectedConcurrentCycles(int feature) {
            if (feature == 8) {
                // A cycle ends with the cleanup pause or is aborted by a full collection
                return count(/\[GC cleanup/) + count(/concurrent-mark-abort/)
            }
            return count(/\]\[gc\s*\] GC\(\d+\) Concurrent (Mark |Undo )?Cycle \d/)
        }

        int toSpaceExhaustedCount() {
            return count(/To-space exhausted|\(to-space exhausted\)|\]\[gc\s*\] GC\(\d+\) Pause .*\(Evacuation Failure/)
        }

        boolean hasAgeTables() {
            return lines.any { it ==~ /(^|.* )- age +\d+:.*/ }
        }

        int expectedSafepoints(int feature) {
            if (feature == 8) {
                return count(/^\s*\d+[.,]\d+: .+\[\s*\d+\s+\d+\s+\d+\s*\]\s+\[\s*\d+\s+\d+\s+\d+\s+\d+\s+\d+\s*\]/)
            }
            if (feature < 13) {
                return count(/Total time for which application threads were stopped/)
            }
            return count(/\]\[safepoint\s*\] Safepoint "/)
        }
    }
}
